public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    StringBuffer unicode = new StringBuffer();
    Matcher m = Pattern.compile("(\\\\(u[0-9A-Fa-f]{4}|[nrftvb]))")
                    .matcher(str.replaceAll("(\\\\*)", ""));

    while (m.find()) {
        switch (m.group(2)) {
            case "n":
                unicode.append("\n");
                break;
            case "r":
                unicode.append("\r");
                break;
            case "f":
                unicode.append("\f");
                break;
            case "t":
                unicode.append("\t");
                break;
            case "v":
                unicode.append("\v");
                break;
            case "b":
                unicode.append("\b");
                break;
            default:
                unicode.append("\\")
                    .append(m.group(2))
                    .append(m.group(3));
        }
    }

    return unicode.toString();
}
