public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    if (!file.exists() || !file.canRead() || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("The file or the time ranges are not specified or invalid");
    }

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split(",");
            if (parts.length == 3 && threadSnapshots.size() < timeRanges.size()) {
                ThreadSnapshot threadSnapshot = ThreadSnapshot.parseFromString(parts);
                threadSnapshots.add(threadSnapshot);
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading from the file", e);
    }

    return threadSnapshots;
}
